import { validateRoadmap,validateReadiness } from './model.mjs';
import { validateWorkspace, migrateLegacy, MAX_BACKUP_BYTES, COLLECTIONS } from './workspace.mjs';
export const MAX_ROADMAP_FILE_BYTES=2_000_000;
const encoder=new TextEncoder();
const md=value=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/([\\`*_\[\]|])/g,'\\$1').replace(/[\r\n]+/g,' ');
function document(title,summary,type,data,limit){const result=`# ${md(title)}\n\n${summary}\n\n## Restore data\n\nThis structured block preserves the complete data for import. The tables above are a readable summary; edit this block to change the imported data.\n\n<!-- mightora:${type}:v1 -->\n\n\`\`\`json\n${JSON.stringify(data).replace(/</g,'\\u003c').replace(/`/g,'\\u0060')}\n\`\`\`\n`;if(encoder.encode(result).length>limit)throw new Error('This Markdown export exceeds the supported file limit.');return result;}
function payload(source,type,limit){if(typeof source!=='string'||encoder.encode(source).length>limit)throw new Error('Markdown file exceeds the supported size limit.');const normalized=source.replace(/^\uFEFF/,'').replace(/\r\n/g,'\n');const marker=`<!-- mightora:${type}:v1 -->`;if(normalized.split(marker).length!==2)throw new Error(`Choose a Mightora ${type} Markdown file containing one restore-data block.`);const after=normalized.split(marker)[1],match=after.match(/^\s*```json\n([\s\S]*?)\n```(?:\s|$)/);if(!match)throw new Error('The Markdown restore-data block is missing or malformed.');try{return JSON.parse(match[1]);}catch{throw new Error('The Markdown restore-data block contains invalid JSON.');}}
export function roadmapToMarkdown(r){validateReadiness(validateRoadmap(r));const tracks=new Map(r.tracks.map(t=>[t.id,t.name]));const summary=`**Client / workspace:** ${md(r.client)}\n\n**Start:** ${r.startDate} · **Quarters:** ${r.periodCount}\n\n## Workstreams\n\n| ID | Workstream | Colour |\n| --- | --- | --- |\n${r.tracks.map(t=>`| ${md(t.id)} | ${md(t.name)} | ${t.color} |`).join('\n')}\n\n## Activities and dependencies\n\n| ID | Activity | Workstream | Start | Finish | Status | Owner | Depends on |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n${r.activities.map(a=>`| ${md(a.id)} | ${md(a.title)} | ${md(tracks.get(a.trackId))} | ${a.start} | ${a.end} | ${a.status} | ${md(a.owner)} | ${a.dependencies.map(md).join(', ')||'—'} |`).join('\n')}`;return document(r.title,summary,'roadmap',r,MAX_ROADMAP_FILE_BYTES);}
export function roadmapFromMarkdown(source){return validateReadiness(validateRoadmap(payload(source,'roadmap',MAX_ROADMAP_FILE_BYTES)));}
export function workspaceToMarkdown(workspace){if(workspace?.format==='mightora-workspace-backup')workspace=migrateLegacy(workspace);validateWorkspace(workspace);const summary=`## Included data\n\n| Collection | Records |\n| --- | --- |\n${COLLECTIONS.map(name=>`| ${name} | ${workspace[name].length} |`).join('\n')}\n\n## Roadmaps\n\n${workspace.roadmaps.map(r=>`- **${md(r.roadmap.title)}** — ${r.roadmap.tracks.length} workstreams, ${r.roadmap.activities.length} activities`).join('\n')||'No roadmaps.'}`;return document('Mightora workspace backup',summary,'workspace',workspace,MAX_BACKUP_BYTES);}
export function workspaceFromMarkdown(source){const data=payload(source,'workspace',MAX_BACKUP_BYTES);return data?.format==='mightora-workspace-backup'?migrateLegacy(data):validateWorkspace(data);}
export function reportToMarkdown(report){const summary=`**Generated:** ${new Date(report.at).toISOString()}\n\n| Roadmap | Activities | Complete | In progress |\n| --- | --- | --- | --- |\n${report.roadmaps.map(r=>`| ${md(r.title)} | ${r.activities} | ${r.done} | ${r.inProgress} |`).join('\n')}\n\n**Totals:** ${report.totals.roadmaps} roadmaps, ${report.totals.activities} activities, ${report.totals.done} complete.`;return document('Mightora portfolio report',summary,'report',report,MAX_BACKUP_BYTES);}
